using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;
namespace OneTaskBar
{
    internal static class StartDataChecks
    {
        const string card=@"{""body"":[{""type"":""TextBlock"",""text"":""테스트 휴대폰""},{""type"":""ColumnSet"",""columns"":[{""type"":""Column"",""items"":[{""type"":""Image"",""altText"":""PC와 연결됨""},{""type"":""Image"",""altText"":""Bluetooth가 켜져 있습니다.""},{""type"":""TextBlock"",""text"":""75%""}]}]},{""type"":""Container"",""items"":[{""type"":""ColumnSet"",""selectAction"":{""url"":""ms-phone:messages?deviceid=00000000-0000-0000-0000-000000000001""}},{""type"":""ColumnSet"",""selectAction"":{""url"":""ms-phone:calling""}},{""type"":""ColumnSet"",""selectAction"":{""url"":""ms-phone:photos""}},{""type"":""ColumnSet"",""selectAction"":{""url"":""ms-phone:filetransfer""}},{""type"":""ColumnSet"",""selectAction"":{""url"":""ms-phone:remoting?packagename=arbitrary.app""},""text"":""Private recent activity must not be shown""}]}],""companionActions"":[{""url"":""ms-phone:""},{""url"":""ms-phone:remoting?packagename=yourphone.phonescreen""}]}";
        internal static PhoneSnapshot Phone(){return PhoneCompanion.Parse(card,DateTime.UtcNow);}
        internal static void Validate(List<string> checks)
        {
            string path=Path.Combine(AppLog.Data,"start-folder-fixture.json");var apps=Enumerable.Range(1,5).Select(i=>new AppEntry {Name="Fixture "+i,Target="fixture:"+i}).ToList();
            File.WriteAllText(path,new JavaScriptSerializer().Serialize(apps.Select(a=>new Catalog.PinPreference {Key=a.Key,Name=a.Name,Target=a.Target}).ToList()));var store=new StartPinStore(path);
            Require(store.Resolve(apps).Select(a=>a.Key).SequenceEqual(apps.Select(a=>a.Key)),"legacy pin migration/order");Require(store.Combine(apps[0].Key,apps[1].Key),"create folder");var folder=store.Tiles(apps).First(t=>t.Folder);Require(store.Combine(apps[2].Key,folder.Key)&&!store.Combine(folder.Key,apps[3].Key),"add app/reject nested folder");
            Require(store.Rename(folder.Key,"개발 도구")&&store.MoveWithin(folder.Key,apps[1].Key,apps[2].Key,true),"rename/reorder children");var restored=new StartPinStore(path);var loaded=restored.Tiles(apps).First(t=>t.Folder);Require(loaded.Name=="개발 도구"&&loaded.Children.Select(t=>t.Key).SequenceEqual(new[]{apps[0].Key,apps[2].Key,apps[1].Key}),"folder round trip");
            Require(restored.Move(folder.Key,apps[4].Key,true)&&restored.Tiles(apps).Last().Key==folder.Key,"move whole folder");Require(restored.Extract(apps[0].Key)&&restored.Contains(apps[0]),"extract preserves pin");restored.Set(apps[2],false);Require(!restored.Contains(apps[2])&&restored.FolderCount==1,"unpin one child");Require(restored.Dissolve(folder.Key)&&restored.FolderCount==0&&restored.Resolve(apps).Count==4,"dissolve preserves remaining apps");
            restored.Replace(apps.Take(2));Require(restored.Combine(apps[0].Key,apps[1].Key),"second folder");restored.Set(apps[0],false);restored.Set(apps[1],false);Require(restored.FolderCount==0&&new StartPinStore(path).Resolve(apps).Count==0,"empty folder cleanup/no reseed");checks.Add("Start folders preserve legacy pins, rename/child order, whole-folder movement, extraction, unpinning and empty-folder cleanup across reloads");
            var installed=Enumerable.Range(1,510).Select(i=>new AppEntry {Name="Installed "+i,Target="installed:"+i}).ToList();string drawerPath=Path.Combine(AppLog.Data,"apps-layout-fixture-"+Guid.NewGuid().ToString("N")+".json");var drawer=new StartPinStore(drawerPath,4096);drawer.Reconcile(installed);Require(drawer.Resolve(installed).Count==510,"all-apps capacity beyond Start pin limit");Require(drawer.Move(installed[0].Key,installed[3].Key,true)&&drawer.Combine(installed[1].Key,installed[2].Key),"all-apps order/folder");var drawerFolder=drawer.Tiles(installed).First(t=>t.Folder);drawer.Rename(drawerFolder.Key,"사진과 도구");var before=drawer.Resolve(installed).Select(a=>a.Key).ToArray();var more=installed.Skip(2).Concat(new[]{new AppEntry {Name="New install",Target="installed:new"}}).ToList();drawer.Reconcile(more);var allAgain=new StartPinStore(drawerPath,4096);var againTiles=allAgain.Tiles(more);Require(allAgain.Resolve(more).Select(a=>a.Key).SequenceEqual(before.Where(k=>k!=installed[0].Key&&k!=installed[1].Key).Concat(new[]{more.Last().Key})),"new installs append and removals preserve existing order");Require(againTiles.Any(t=>t.Key==drawerFolder.Key&&t.Name=="사진과 도구"&&t.Children.Count==1),"folder persists after one app uninstall");allAgain.Reconcile(new List<AppEntry>());Require(allAgain.Resolve(more).Count==509&&restored.Resolve(apps).Count==0,"transient empty catalog and independent Start layout");checks.Add("All-apps layout supports 510 apps, independent folders/order, renamed-folder persistence, app installation/removal and transient empty catalogs without altering Start pins");
            var notificationAudio=new JavaScriptSerializer().Deserialize<PreferenceData>(new JavaScriptSerializer().Serialize(new PreferenceData {NotificationSoundEnabled=true,NotificationSoundFile=@"C:\sounds\알림.wav"}));
            Require(!new PreferenceData().NotificationSoundEnabled&&new PreferenceData().NotificationSoundFile==null&&notificationAudio.NotificationSoundEnabled&&ChargeSound.Supported(notificationAudio.NotificationSoundFile),"custom notification audio is optional and persists independently from charger audio");
            var defaults=new JavaScriptSerializer().Deserialize<PreferenceData>("{}");var sound=new JavaScriptSerializer().Deserialize<PreferenceData>(new JavaScriptSerializer().Serialize(new PreferenceData {ChargeSoundEnabled=true,ChargeSoundFile=@"C:\sounds\연결음.MP3"}));Require(!defaults.ChargeSoundEnabled&&defaults.ChargeSoundFile==null&&sound.ChargeSoundEnabled&&sound.ChargeSoundFile.EndsWith("연결음.MP3")&&ChargeSound.Supported(sound.ChargeSoundFile)&&!ChargeSound.Supported("file.exe"),"optional custom charger sound persistence");var edge=new ChargeState();Require(!edge.Observe(true)&&!edge.Observe(true)&&!edge.Observe(false)&&edge.Observe(true)&&!edge.Observe(true),"charger sound startup/deduplicated connection edge");checks.Add("Custom charger audio is off by default, persists the chosen file and triggers once per connection without startup playback");
            var phone=Phone();Require(phone.Available&&phone.Name=="테스트 휴대폰"&&phone.Connected==true&&phone.Bluetooth==true&&phone.Battery=="75%"&&phone.Actions.Count==6,"native Phone Link header/shortcuts");Require(PhoneCompanion.SafeAction("https://example.invalid/")==null&&PhoneCompanion.SafeAction("ms-phone:remoting?packagename=arbitrary.app")==null&&!PhoneCompanion.SafeAction("ms-phone:calling?phonenumber=12345").Contains("12345"),"safe generic phone actions");Require(!PhoneCompanion.Parse("{",DateTime.UtcNow).Available&&!PhoneCompanion.Parse(new string('x',1048577),DateTime.UtcNow).Available,"unavailable/malformed/oversize card");
            string file=Path.Combine(AppLog.Data,"phone-card-fixture.json");File.WriteAllText(file,card);var first=PhoneCompanion.ReadFile(file);int reads=PhoneCompanion.Reads;Require(Object.ReferenceEquals(first,PhoneCompanion.ReadFile(file))&&PhoneCompanion.Reads==reads,"unchanged phone card cache");File.WriteAllText(file,card.Replace("75%","74%"));File.SetLastWriteTimeUtc(file,DateTime.UtcNow.AddSeconds(3));Require(PhoneCompanion.ReadFile(file).Battery=="74%"&&PhoneCompanion.Reads==reads+1,"phone card invalidation");checks.Add("Phone Link parses only native Start header/generic actions, strips launch arguments, caches unchanged files and handles stale/unavailable metadata without polling");
        }
        static void Require(bool value,string name){if(!value)throw new InvalidOperationException("Start data: "+name);}
    }
}
